/**
 * The house design baseline (dsh-design-baseline v1.1.0), vendored so the
 * bundle carries it itself.
 *
 * Why vendored rather than imported from the baseline package: a DSH client
 * bundle is not an ES module. It is a `window.__ModuleLoader__.load({ id,
 * factory(require) })` factory whose require only resolves platform seed
 * names, already-materialized ids and registered factories — never a file path.
 *
 * Generated from dsh-design-baseline/dist/theme.js — do not edit by hand.
 * Regenerate: cp ../dsh-design-baseline/dist/theme.js src/client/baseline.ts
 * (keeping this header), then rebuild.
 */
// Generated by dsh-design-baseline/build.mjs — do not edit by hand.
// Source of truth: dsh-design-baseline/baseline.css (v1.1.0).
//
// The house style for every DSH plugin I write: neutral surfaces come from the
// host, colour comes from nowhere else except the six accents below. The look
// is the FreeLLMAPI router dashboard, approved as the default.

export const BASELINE_VERSION = "1.1.0"

/** The full .dsb-* stylesheet. Inject once per plugin. */
export const BASELINE_CSS = "/* ============================================================================\n   DSH plugin design baseline  ·  dsh-design-baseline v1\n   ----------------------------------------------------------------------------\n   Derived from the FreeLLMAPI router dashboard (:3001) theme, which is the\n   look approved as the house style for every DSH plugin I write.\n\n   The whole point of this file is one rule:\n\n       Neutral surfaces come from the DSH host. Colour comes from nowhere else\n       except the six accents below.\n\n   The dashboard's own palette has chroma 0 for every neutral — pure grey\n   (oklch(...% 0 0)). That is why it looks calm: no tint is competing. The only\n   saturated pixels on the entire page are the three score bars and the state\n   dots. Reproduce that and you get the same calm for free.\n\n   Host tokens are referenced by name (--dsw-alias-*) so light/dark switching,\n   including DSH's own theme overrides, is automatic. Every reference carries a\n   literal fallback so a panel still renders if a token is ever renamed.\n   ========================================================================= */\n\n/* IMPORTANT — why this is body/.dsb-root and not :root.\n   The host declares its dark overrides on `body[data-ds-dark-theme]`, not on\n   :root. A var(--dsw-alias-x, fallback) resolved at :root therefore never sees\n   the dark values and silently sticks to the light fallback (this bit me: the\n   whole panel rendered in light colours while the app was dark). Resolving the\n   mapping on body — or on your plugin's own root element, which is the tidier\n   option — puts it on the same element the host's dark block targets, so the\n   cascade picks the right set in both themes. */\nbody,\n.dsb-root {\n  /* --- accents: the ONLY saturated colours in the system ------------------ */\n  --dsb-accent-stability:    #22c55e;  /* emerald-500 — reliability  */\n  --dsb-accent-speed:        #3b82f6;  /* blue-500    — throughput   */\n  --dsb-accent-intelligence: #a855f7;  /* violet-500  — capability   */\n  --dsb-accent-warn:         #f59e0b;  /* amber-500   — rate limited */\n  --dsb-accent-error:        #f43f5e;  /* rose-500    — invalid/error*/\n  --dsb-accent-info:         #06b6d4;  /* cyan-500    — vision/info  */\n\n  /* Soft washes for badges and chips: 15% of the accent, per the dashboard. */\n  --dsb-wash-stability:    color-mix(in srgb, var(--dsb-accent-stability) 15%, transparent);\n  --dsb-wash-warn:         color-mix(in srgb, var(--dsb-accent-warn) 15%, transparent);\n  --dsb-wash-error:        color-mix(in srgb, var(--dsb-accent-error) 15%, transparent);\n  --dsb-wash-info:         color-mix(in srgb, var(--dsb-accent-info) 15%, transparent);\n  --dsb-wash-brand:        color-mix(in srgb, var(--dsb-accent-intelligence) 15%, transparent);\n\n  /* --- neutrals: mapped from the host, never hardcoded ------------------- */\n  --dsb-surface:          var(--dsw-alias-bg-layer-1, #ffffff);\n  --dsb-surface-2:        var(--dsw-alias-bg-layer-2, #fafafa);\n  --dsb-surface-3:        var(--dsw-alias-bg-layer-3, #f5f5f5);\n  --dsb-card:             var(--dsw-alias-bg-module-platform, #f9fafb);\n  --dsb-track:            var(--dsw-alias-bg-layer-2, #f5f5f5);\n\n  --dsb-line:             var(--dsw-alias-border-l1, #0000000a);\n  --dsb-line-strong:      var(--dsw-alias-border-l2, #0000001a);\n\n  --dsb-text:             var(--dsw-alias-label-primary, #0f1115);\n  --dsb-text-secondary:   var(--dsw-alias-label-secondary, #61666b);\n  --dsb-text-tertiary:    var(--dsw-alias-label-tertiary, #81858c);\n  --dsb-text-caption:     var(--dsw-alias-label-caption, #adb2b8);\n\n  --dsb-inverted-bg:      var(--dsw-alias-label-primary, #0f1115);\n  --dsb-inverted-fg:      var(--dsw-alias-label-primary-foreground, #ffffff);\n  --dsb-hover:            var(--dsw-alias-interactive-bg-hover, #2631480f);\n  --dsb-hover-strong:     var(--dsw-alias-interactive-bg-hover-accent, #26314824);\n\n  /* --- geometry ---------------------------------------------------------- */\n  --dsb-radius:      12px;   /* cards, grouped chips, tables  */\n  --dsb-radius-sm:   8px;    /* buttons inside those, tabs    */\n  --dsb-radius-pill: 9999px; /* bars, chips, badges, dots     */\n  --dsb-gap:         12px;\n\n  --dsb-font: var(--dsw-font-family, \"Geist Variable\", -apple-system,\n                \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif);\n  --dsb-font-mono: var(--ds-font-family-code, \"Geist Mono Variable\",\n                ui-monospace, SFMono-Regular, Menlo, monospace);\n}\n\n/* ---------------------------------------------------------------------------\n   1. Surfaces\n   ------------------------------------------------------------------------ */\n\n.dsb-card {\n  border: 1px solid var(--dsb-line-strong);\n  border-radius: var(--dsb-radius);\n  background: var(--dsb-surface);\n  padding: 16px;\n  color: var(--dsb-text);\n  font-family: var(--dsb-font);\n}\n\n.dsb-card--flush { padding: 0; }\n\n.dsb-card-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--dsb-gap);\n  margin-bottom: 12px;\n}\n\n.dsb-title {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  color: var(--dsb-text);\n}\n\n.dsb-subtitle {\n  margin: 2px 0 0;\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--dsb-text-secondary);\n}\n\n.dsb-muted { color: var(--dsb-text-secondary); }\n.dsb-caption {\n  font-size: 11px;\n  color: var(--dsb-text-caption);\n}\n\n/* Section divider: a hairline, never a filled band. */\n.dsb-divider {\n  height: 1px;\n  border: 0;\n  margin: 16px 0;\n  background: var(--dsb-line-strong);\n}\n\n/* ---------------------------------------------------------------------------\n   2. The score bar — the signature element\n   Track 48×6px, pill, --dsb-track. Fill: display:block, width %, pill.\n   NOTE: the fill MUST be display:block. As an inline <span> its width and\n   height are ignored and the bar silently disappears, leaving only the grey\n   track. That exact bug shipped once; do not let it back in.\n   ------------------------------------------------------------------------ */\n\n.dsb-bar {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  white-space: nowrap;\n}\n\n.dsb-bar-track {\n  position: relative;\n  width: 48px;\n  height: 6px;\n  flex: 0 0 48px;\n  border-radius: var(--dsb-radius-pill);\n  background: var(--dsb-track);\n  overflow: hidden;\n}\n\n.dsb-bar-fill {\n  display: block;\n  height: 100%;\n  border-radius: var(--dsb-radius-pill);\n  background: var(--dsb-accent-speed);\n  transition: width 150ms ease-out;\n}\n\n.dsb-bar-fill--stability    { background: var(--dsb-accent-stability); }\n.dsb-bar-fill--speed        { background: var(--dsb-accent-speed); }\n.dsb-bar-fill--intelligence { background: var(--dsb-accent-intelligence); }\n\n/* No data: a dashed outline and an en dash. Never draw a 0-width bar and let\n   it read as \"scores zero\". */\n.dsb-bar--empty .dsb-bar-track {\n  background: transparent;\n  border: 1px dashed color-mix(in srgb, var(--dsb-text-tertiary) 40%, transparent);\n}\n\n.dsb-bar-num {\n  width: 28px;\n  text-align: right;\n  font-family: var(--dsb-font-mono);\n  font-size: 11px;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsb-text-secondary);\n}\n\n/* ---------------------------------------------------------------------------\n   3. State dot\n   ------------------------------------------------------------------------ */\n\n.dsb-dot {\n  display: inline-block;\n  width: 6px;\n  height: 6px;\n  flex: 0 0 6px;\n  border-radius: var(--dsb-radius-pill);\n  background: var(--dsb-text-tertiary);\n}\n\n.dsb-dot--healthy { background: var(--dsb-accent-stability); }\n.dsb-dot--warn    { background: var(--dsb-accent-warn); }\n.dsb-dot--error   { background: var(--dsb-accent-error); }\n.dsb-dot--idle    { background: var(--dsb-text-tertiary); }\n\n/* ---------------------------------------------------------------------------\n   4. Segmented control — grouped options inside one pill-ish frame\n   ------------------------------------------------------------------------ */\n\n.dsb-segmented {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px;\n  border: 1px solid var(--dsb-line-strong);\n  border-radius: var(--dsb-radius);\n}\n\n.dsb-seg {\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--dsb-radius-sm);\n  background: transparent;\n  color: var(--dsb-text-secondary);\n  font-family: inherit;\n  font-size: 12px;\n  line-height: 1.4;\n  cursor: pointer;\n  transition: background-color 150ms, color 150ms;\n}\n\n.dsb-seg:hover { background: var(--dsb-hover); color: var(--dsb-text); }\n\n/* Selected = inverted, not coloured. Colour is reserved for data. */\n.dsb-seg[aria-pressed=\"true\"],\n.dsb-seg[data-selected=\"true\"] {\n  background: var(--dsb-inverted-bg);\n  color: var(--dsb-inverted-fg);\n  font-weight: 500;\n}\n\n/* ---------------------------------------------------------------------------\n   5. Chips and badges\n   ------------------------------------------------------------------------ */\n\n.dsb-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 2px 6px;\n  border-radius: var(--dsb-radius-pill);\n  background: var(--dsb-surface-3);\n  color: var(--dsb-text-secondary);\n  font-size: 10px;\n  line-height: 1.6;\n  white-space: nowrap;\n}\n\n.dsb-chip--active {\n  background: var(--dsb-inverted-bg);\n  color: var(--dsb-inverted-fg);\n  font-weight: 500;\n}\n\n.dsb-chip--stability    { background: var(--dsb-wash-stability); color: var(--dsb-accent-stability); }\n.dsb-chip--warn         { background: var(--dsb-wash-warn);      color: var(--dsb-accent-warn); }\n.dsb-chip--error        { background: var(--dsb-wash-error);     color: var(--dsb-accent-error); }\n.dsb-chip--info         { background: var(--dsb-wash-info);      color: var(--dsb-accent-info); }\n.dsb-chip--brand        { background: var(--dsb-wash-brand);     color: var(--dsb-accent-intelligence); }\n\n/* In dark mode the 15% wash over a dark surface needs a lighter source colour\n   to stay legible; the host's dark flag drives the swap. */\n[data-ds-dark-theme] .dsb-chip--stability,\n.dark .dsb-chip--stability { color: color-mix(in srgb, var(--dsb-accent-stability) 70%, white); }\n[data-ds-dark-theme] .dsb-chip--warn,\n.dark .dsb-chip--warn      { color: color-mix(in srgb, var(--dsb-accent-warn) 70%, white); }\n[data-ds-dark-theme] .dsb-chip--error,\n.dark .dsb-chip--error     { color: color-mix(in srgb, var(--dsb-accent-error) 70%, white); }\n\n/* ---------------------------------------------------------------------------\n   6. Tabs — underline on the active one, no pill fill\n   ------------------------------------------------------------------------ */\n\n.dsb-tabs {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  border-bottom: 1px solid var(--dsb-line-strong);\n}\n\n.dsb-tab {\n  position: relative;\n  padding: 8px 0 10px;\n  border: 0;\n  background: transparent;\n  color: var(--dsb-text-secondary);\n  font-family: inherit;\n  font-size: 13px;\n  cursor: pointer;\n}\n\n.dsb-tab:hover { color: var(--dsb-text); }\n\n.dsb-tab[aria-selected=\"true\"],\n.dsb-tab[data-selected=\"true\"] {\n  color: var(--dsb-text);\n  font-weight: 500;\n}\n\n.dsb-tab[aria-selected=\"true\"]::after,\n.dsb-tab[data-selected=\"true\"]::after {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: -1px;\n  height: 2px;\n  border-radius: 2px 2px 0 0;\n  background: var(--dsb-text);\n}\n\n/* ---------------------------------------------------------------------------\n   7. Table row — hairline separators, transparent background\n   ------------------------------------------------------------------------ */\n\n.dsb-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n  color: var(--dsb-text);\n}\n\n.dsb-table th {\n  padding: 8px 12px 8px 0;\n  text-align: left;\n  font-size: 11px;\n  font-weight: 500;\n  color: var(--dsb-text-secondary);\n  border-bottom: 1px solid var(--dsb-line-strong);\n  white-space: nowrap;\n}\n\n.dsb-table td {\n  padding: 8px 12px 8px 0;\n  vertical-align: middle;\n  border-bottom: 1px solid var(--dsb-line);\n}\n\n.dsb-table tr:last-child td { border-bottom: 0; }\n.dsb-table tbody tr:hover { background: var(--dsb-hover); }\n\n.dsb-num {\n  font-family: var(--dsb-font-mono);\n  font-variant-numeric: tabular-nums;\n}\n\n.dsb-row-index {\n  width: 28px;\n  color: var(--dsb-text-caption);\n  font-family: var(--dsb-font-mono);\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n}\n\n.dsb-row-id {\n  font-family: var(--dsb-font-mono);\n  font-size: 12px;\n  color: var(--dsb-text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.dsb-row-dim { opacity: 0.55; }\n\n/* ---------------------------------------------------------------------------\n   8. Toggle\n   ------------------------------------------------------------------------ */\n\n.dsb-switch {\n  position: relative;\n  width: 34px;\n  height: 20px;\n  flex: 0 0 34px;\n  padding: 0;\n  border: 0;\n  border-radius: var(--dsb-radius-pill);\n  background: color-mix(in srgb, var(--dsb-text-tertiary) 28%, transparent);\n  cursor: pointer;\n  transition: background-color 150ms;\n}\n\n.dsb-switch::after {\n  content: \"\";\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  background: var(--dsb-inverted-fg);\n  transition: transform 150ms ease-out;\n}\n\n.dsb-switch[aria-checked=\"true\"] { background: var(--dsb-accent-stability); }\n.dsb-switch[aria-checked=\"true\"]::after { transform: translateX(14px); }\n\n/* Disabled stays readable: dim the track, not the whole row. */\n.dsb-switch:disabled { opacity: 0.4; cursor: default; }\n\n/* ---------------------------------------------------------------------------\n   9. Buttons\n   ------------------------------------------------------------------------ */\n\n.dsb-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 6px 12px;\n  border: 1px solid var(--dsb-line-strong);\n  border-radius: var(--dsb-radius-sm);\n  background: transparent;\n  color: var(--dsb-text);\n  font-family: inherit;\n  font-size: 12px;\n  line-height: 1.5;\n  text-decoration: none;\n  cursor: pointer;\n  transition: background-color 150ms;\n}\n\n.dsb-btn:hover { background: var(--dsb-hover); }\n.dsb-btn:disabled { opacity: 0.45; cursor: default; background: transparent; }\n\n.dsb-btn--primary {\n  border-color: transparent;\n  background: var(--dsb-inverted-bg);\n  color: var(--dsb-inverted-fg);\n  font-weight: 500;\n}\n\n.dsb-btn--primary:hover { background: var(--dsb-inverted-bg); opacity: 0.9; }\n\n.dsb-btn--danger { color: var(--dsb-accent-error); }\n\n/* ---------------------------------------------------------------------------\n   10. Empty state\n   ------------------------------------------------------------------------ */\n\n.dsb-empty {\n  padding: 32px 16px;\n  text-align: center;\n  font-size: 12px;\n  color: var(--dsb-text-secondary);\n}\n\n.dsb-empty--error { color: var(--dsb-accent-error); }\n"

/**
 * The same tokens as plain CSS values, for plugins that style with inline
 * objects instead of class names. Use these rather than your own hex values —
 * a plugin that invents its own grey is the one thing this baseline exists to
 * prevent.
 */
export const THEME = Object.freeze({
  text: "var(--dsw-alias-label-primary, #0f1115)",
  textSecondary: "var(--dsw-alias-label-secondary, #61666b)",
  textTertiary: "var(--dsw-alias-label-tertiary, #81858c)",
  textCaption: "var(--dsw-alias-label-caption, #adb2b8)",
  surface: "var(--dsw-alias-bg-layer-1, #ffffff)",
  surface2: "var(--dsw-alias-bg-layer-2, #fafafa)",
  surface3: "var(--dsw-alias-bg-layer-3, #f5f5f5)",
  card: "var(--dsw-alias-bg-module-platform, #f9fafb)",
  track: "var(--dsw-alias-bg-layer-2, #f5f5f5)",
  line: "var(--dsw-alias-border-l1, rgba(0,0,0,0.04))",
  lineStrong: "var(--dsw-alias-border-l2, rgba(0,0,0,0.10))",
  hover: "var(--dsw-alias-interactive-bg-hover, rgba(38,49,72,0.06))",
  invertedBg: "var(--dsw-alias-label-primary, #0f1115)",
  invertedFg: "var(--dsw-alias-label-primary-foreground, #ffffff)",
  primaryFill: "var(--dsw-alias-button-primary-fill, #3b82f6)",
  primaryFg: "var(--dsw-alias-label-primary-foreground, #ffffff)",
  accentStability: "#22c55e",
  accentSpeed: "#3b82f6",
  accentIntelligence: "#a855f7",
  accentWarn: "#f59e0b",
  accentError: "#f43f5e",
  accentInfo: "#06b6d4",
  radius: "12px",
  radiusSm: "8px",
  radiusPill: "9999px",
  gap: "12px",
})

/** A 15% wash of an accent, for badges and chips. */
export function wash(accent) {
  return `color-mix(in srgb, ${accent} 15%, transparent)`
}

/**
 * Appends the stylesheet to a document exactly once.
 *
 * Returns the <style> element. Safe to call from every component that might
 * mount first; the check is by attribute, not by module state, so two copies of
 * this module still cannot double-inject.
 *
 * Pass a doc to target something other than the global document (tests).
 */
export function injectBaseline(doc, id) {
  const target = doc || (typeof document === 'undefined' ? null : document)
  if (!target || !target.head) return null
  const key = id || 'dsh-design-baseline'
  const existing = target.querySelector(`style[data-dsb="${key}"]`)
  if (existing) return existing
  const style = target.createElement('style')
  style.dataset.dsb = key
  style.dataset.plugin = key
  style.textContent = BASELINE_CSS
  target.head.appendChild(style)
  return style
}
